// Guided browser adapter loaded after the legacy adapter.
analyze=function(img,seed=window.flowerSeed){const scale=Math.min(256/img.naturalWidth,256/img.naturalHeight),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));canvas.width=w;canvas.height=h;ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);const out=FlowerEngine.analyze(ctx.getImageData(0,0,w,h).data,w,h,ENGINE_PROFILES,{minimumScore:Number($('scoreThreshold').value),minimumLead:Number($('marginThreshold').value),seed});for(const [name,id] of [['flower','maskPreview'],['leaf','leafMaskPreview'],['context','contextMaskPreview']]){const c=$(id);c.width=w;c.height=h;const cctx=c.getContext('2d'),pixels=cctx.createImageData(w,h);for(let p=0;p<w*h;p++){const value=out.masks[name][p]?255:18;pixels.data.set([value,value,value,255],p*4)}cctx.putImageData(pixels,0,0)}delete out.masks;return out};
render=function(out){lastOutput=out;const top=out.candidates[0],usable=out.quality.usable;$('prediction').textContent=usable?top.name:'NO RELIABLE REGION';$('latin').textContent=usable?top.latin:'—';$('growthStage').textContent='Unknown'+(usable?' · hypothesis: '+top.stage:'');$('plantPart').textContent=usable?top.part:'—';$('decision').textContent='REVIEW REQUIRED';$('topScore').textContent=top.score.toFixed(3);$('leadScore').textContent=out.decision.lead.toFixed(3);$('runStatus').textContent=out.quality.seeded?'GUIDED · EXPERIMENTAL':'TAP REQUIRED';$('runStatus').className='status idle';$('decisionLog').textContent=(out.quality.issues.length?out.quality.issues.join('. ')+'. ':'')+out.decision.reason+' '+out.decision.follow_up;if($('captureFeedback'))$('captureFeedback').textContent=usable?`Mask selected · ${out.features.structural_class} · visible-tip range ${Math.round(out.features.visible_tips_low*20)}–${Math.round(out.features.visible_tips_high*20)}.`:`Try again: ${out.quality.issues.join('; ')}`;const categories={COLOUR:['pink','red','yellow','blue','pale'],OUTLINE:['circularity','solidity','aspect_ratio','symmetry'],PETAL_CUES:['visible_tips_low','visible_tips_high','tip_stability'],CENTRE:['center_yellow','outer_yellow','centre_contrast'],CONTEXT:['vegetation_coverage','vegetation_below']};$('featureRows').innerHTML=Object.entries(categories).map(([title,keys])=>`<section class="feature-group"><h3>${title}</h3>${keys.map(key=>{const value=out.features[key];return `<div class="feature-item"><div class="feature-label"><span>${key.replaceAll('_',' ')}</span><strong>${value==null?'N/A':value.toFixed(3)}</strong></div><div class="bar"><span style="width:${Math.min(100,(value||0)*100)}%"></span></div></div>`}).join('')}</section>`).join('');document.querySelector('.candidates thead').innerHTML='<tr><th>#</th><th>Candidate / stage hypothesis</th><th>Colour</th><th>Shape</th><th>Centre</th><th>Surface</th><th>Match strength</th></tr>';$('candidateRows').innerHTML=out.candidates.map(row=>`<tr><td>${row.rank}</td><td>${row.name}<br><small>${row.stage} · ${row.taxonRank}</small></td>${['colour','shape','centre','surface'].map(k=>`<td>${row.parts[k]==null?'—':row.parts[k].toFixed(2)}</td>`).join('')}<td>${row.score.toFixed(3)}</td></tr>`).join('');const strengths=top.evidence.filter(e=>!e.contradiction),conflicts=top.evidence.filter(e=>e.contradiction);$('rawOutput').textContent=`CANDIDATE EVIDENCE — ${top.name}\nThese are experimental feature ranges, not botanical proof.\n\nMATCHED\n${strengths.map(e=>`${e.feature}: ${e.value.toFixed(3)} in [${e.expected.join(', ')}]`).join('\n')}\n\nCONFLICTS\n${conflicts.map(e=>`${e.feature}: ${e.value.toFixed(3)} outside [${e.expected.join(', ')}]`).join('\n')||'None among measured features'}\n\nSTRUCTURE\n${out.features.structural_class}; visible-tip estimate ${Math.round((out.features.visible_tips_low||0)*20)}–${Math.round((out.features.visible_tips_high||0)*20)} (uncertain when petals overlap).\n\nNEXT EVIDENCE\n${out.decision.follow_up}\n\nUNMEASURED\nFlower tubes, bracts, reproductive column, verified leaf arrangement.\n\nRAW OUTPUT\n${JSON.stringify(out,null,2)}`;$('copyButton').disabled=false;};
document.querySelector('.candidates .panel-head h2').textContent='EXPERIMENTAL CANDIDATES';document.querySelector('.candidates .panel-head span').textContent='uncalibrated match strength, not probability';document.querySelector('.raw h2').textContent='EVIDENCE / RAW OUTPUT';document.querySelector('.features .panel-head span').textContent='flower region only, except context';
window.flowerSeed=null;preview.addEventListener('click',event=>{if(!preview.naturalWidth)return;const rect=preview.getBoundingClientRect(),imageRatio=preview.naturalWidth/preview.naturalHeight,boxRatio=rect.width/rect.height;let drawnWidth=rect.width,drawnHeight=rect.height,left=0,top=0;if(imageRatio>boxRatio){drawnHeight=rect.width/imageRatio;top=(rect.height-drawnHeight)/2}else{drawnWidth=rect.height*imageRatio;left=(rect.width-drawnWidth)/2}const x=(event.clientX-rect.left-left)/drawnWidth,y=(event.clientY-rect.top-top)/drawnHeight;if(x<0||x>1||y<0||y>1)return;window.flowerSeed={x,y};const marker=$('seedMarker');marker.hidden=false;marker.style.left=`${left+x*drawnWidth}px`;marker.style.top=`${top+y*drawnHeight}px`;$('tapInstruction').textContent='Flower selected — tap elsewhere to try another region';processing.hidden=false;requestAnimationFrame(()=>{render(analyze(preview,window.flowerSeed));processing.hidden=true})});
